IMAGE_TOKEN_START = 8192  # 偏移量

# 🚨 极其关键：根据之前的测试，你的 VQGAN 特征图是 16x16，所以需要 256 个 Token
EXPECTED_TOKEN_COUNT = 256
FEATURE_MAP_SIZE = 16

# TARGET_DEVICE = torch.device("cuda:0")
TARGET_DEVICE = torch.device("cpu")
# =====================================================================

def test_gt_reconstruction():
    print("🎨 正在加载 Decoder 进行受控实验...")
    config = OmegaConf.load(VQGAN_CONFIG)
    params = config.model.params if "model" in config else config.params
    model = VQModel(**params)
    
    sd = torch.load(VQGAN_CKPT, map_location="cpu")
    if "state_dict" in sd: sd = sd["state_dict"]
    model.load_state_dict(sd, strict=False)
    model.to(TARGET_DEVICE).eval()

    if not GT_TOKEN_IDS:
        print("🚨 请先在 GT_TOKEN_IDS 变量中填入测试数据！")
        return

    # 1. 🌟 提取属于图像范围的 Token
    # 假设图像字典基址是 8192，大小是 16384。
    valid_image_ids = [x for x in GT_TOKEN_IDS if IMAGE_TOKEN_START <= x < (IMAGE_TOKEN_START + 16384)]
    
    if len(valid_image_ids) < EXPECTED_TOKEN_COUNT:
        print(f"⚠️ 警告：提取到的有效图片 Token 只有 {len(valid_image_ids)} 个！将用最后一个补齐至 {EXPECTED_TOKEN_COUNT} 个。")
        valid_image_ids += [valid_image_ids[-1] if valid_image_ids else IMAGE_TOKEN_START] * (EXPECTED_TOKEN_COUNT - len(valid_image_ids))
    else:
        valid_image_ids = valid_image_ids[:EXPECTED_TOKEN_COUNT]

    # 2. 🌟 核心修复：扒掉伪装！将所有 ID 减去 8192，打回原形
    clean_ids = [int(x) - IMAGE_TOKEN_START for x in valid_image_ids]
    
    # 二次安全校验：确保清理后的 ID 在 [0, 16383] 范围内
    clean_ids = [max(0, min(x, 16383)) for x in clean_ids]

    # 将其转为 PyTorch 需要的一维张量
    clean_ids_tensor = torch.tensor(clean_ids, device=TARGET_DEVICE)
    
    print(f"📊 洗净偏移量后的 Token 样例 (前5个): {clean_ids_tensor[:5].tolist()}")

    with torch.no_grad():
        # 3. 查表并解码
        # 将一维张量传给它，同时用 shape 参数告诉它恢复成 16x16 的空间结构 (Batch, H, W, Channels)
        # 注意：最后一个维度传 -1，让内部的 get_codebook_entry 自动推断通道数 (即 embedding_dim, 通常是 4)
        z_q = model.quantize.get_codebook_entry(clean_ids_tensor, shape=(1, FEATURE_MAP_SIZE, FEATURE_MAP_SIZE, -1))
        
        x_recon = model.decode(z_q)
        
        # 还原图片
        x_recon = torch.clamp((x_recon + 1.0) / 2.0, min=0.0, max=1.0)
        img_np = x_recon.cpu().squeeze(0).permute(1, 2, 0).float().numpy()
        final_img = Image.fromarray((img_np * 255).astype(np.uint8))
        final_img.save("test_gt_reconstruction9.png")
        
    print("✅ 实验完成！请检查 test_gt_reconstruction.png")

if __name__ == "__main__":
    test_gt_reconstruction()


